window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f531b38899c9f05d"]={"versions": [{"id": "FIG-f531b38899c9f05d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockdiagramm der AUTOSAR-Basissoftwarearchitektur (Classic Platform) zur Einordnung des TTCAN-Stacks („AUTOSAR TTCAN Layer Model“). Dargestellt sind die vertikalen Schichten Hardware (<code>µC</code>), <code>Communication drivers</code>, <code>Communication Hardware Abstraction</code>, <code>Communication Services</code> sowie die flankierenden <code>System Services</code>. Graue Hervorhebungen kennzeichnen die spezifisch für TTCAN relevanten bzw. zuständigen Module.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt hierarchisch angeordnete BSW-Module und Abstraktionsebenen:</p>\n<ul class=\"fig-list\"><li><strong>System Services</strong>: <code>Communication Manager</code> (ComM).\n</li><li><strong>Communication Services</strong>: <code>AUTOSAR COM</code>, <code>DCM Diagnostic Com. Manager</code>, <code>PDU Router</code> (PduR), <code>PDU Multiplexer</code> (IpduM), <code>TTCAN Transport Protocol</code> (TTCAN TP), <code>TTCAN State Manager</code> (TTCANSM), <code>Generic NM Interface / NM GW</code> und <code>TTCAN NM</code>.\n</li><li><strong>Communication Hardware Abstraction</strong>: <code>CAN Transceiver</code> (Transceiver-Treiber) und <code>TTCAN Interface</code> (TTCANIf).\n</li><li><strong>Communication drivers</strong>: <code>TTCAN Driver</code> (TTCANDrv).\n</li><li><strong>Hardware / Microcontroller (<code>µC</code>)</strong>: On-Chip-Controller <code>TTCAN</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Abhängigkeiten verlaufen vertikal zwischen PduR/TTCAN TP/TTCANSM/TTCAN NM und TTCAN Interface, vom TTCAN Interface zum TTCAN Driver bzw. CAN Transceiver Driver sowie vom TTCAN Driver zur Hardware-Peripherie.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichtendarstellung ohne explizite Interaktions- oder Sequenzpfeile. Die funktionale Kaskadierung erfolgt vertikal: Steuerungsbefehle des ComM wirken auf den TTCAN State Manager; Anwendungsdaten aus AUTOSAR COM sowie Diagnose-PDUs aus dem DCM werden über PduR und IpduM bzw. über das TTCAN Transport Protocol an das TTCAN Interface gereicht. Das TTCAN Interface abstrahiert den Hardwarezugriff und bedient den TTCAN Driver für zeitgesteuerte Nachrichtenübertragungen (kontinuierliche Übertragung über konfigurierte Tx-Trigger in exklusiven Zeitfenstern) sowie den CAN Transceiver.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektur-Referenzmodell für die Einbettung des TTCAN-Kommunikationsstapels in AUTOSAR. Das Modul <code>TTCAN Interface</code> stellt die zentrale hardwareunabhängige Vermittlungsschicht für TTCAN dar. Es bedient PDU Router, Transportprotokoll, State Manager und Network Management und standardisiert den Zugriff auf hardwarenahe Treiber (<code>TTCAN Driver</code>) sowie Transceiver. Implementierer müssen die korrekte funktionale Anbindung an PduR, TTCANSM und TTCAN Driver gemäß AUTOSAR-SWS-Vorgaben gewährleisten.</p>"}, {"id": "FIG-fe62a074a22c7fb5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockdiagramm der AUTOSAR-Basissoftwarearchitektur (Classic Platform) zur Einordnung des TTCAN-Stacks („AUTOSAR TTCAN Layer Model“). Dargestellt sind die vertikalen Schichten Hardware (<code>µC</code>), <code>Communication drivers</code>, <code>Communication Hardware Abstraction</code>, <code>Communication Services</code> sowie die flankierenden <code>System Services</code>. Graue Hervorhebungen kennzeichnen die spezifisch für TTCAN relevanten bzw. zuständigen Module.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt hierarchisch angeordnete BSW-Module und Abstraktionsebenen:</p>\n<ul class=\"fig-list\"><li><strong>System Services</strong>: <code>Communication Manager</code> (ComM).\n</li><li><strong>Communication Services</strong>: <code>AUTOSAR COM</code>, <code>DCM Diagnostic Com. Manager</code>, <code>PDU Router</code> (PduR), <code>PDU Multiplexer</code> (IpduM), <code>TTCAN Transport Protocol</code> (TTCAN TP), <code>TTCAN State Manager</code> (TTCANSM), <code>Generic NM Interface / NM GW</code> und <code>TTCAN NM</code>.\n</li><li><strong>Communication Hardware Abstraction</strong>: <code>CAN Transceiver</code> (Transceiver-Treiber) und <code>TTCAN Interface</code> (TTCANIf).\n</li><li><strong>Communication drivers</strong>: <code>TTCAN Driver</code> (TTCANDrv).\n</li><li><strong>Hardware / Microcontroller (<code>µC</code>)</strong>: On-Chip-Controller <code>TTCAN</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Abhängigkeiten verlaufen vertikal zwischen PduR/TTCAN TP/TTCANSM/TTCAN NM und TTCAN Interface, vom TTCAN Interface zum TTCAN Driver bzw. CAN Transceiver Driver sowie vom TTCAN Driver zur Hardware-Peripherie.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichtendarstellung ohne explizite Interaktions- oder Sequenzpfeile. Die funktionale Kaskadierung erfolgt vertikal: Steuerungsbefehle des ComM wirken auf den TTCAN State Manager; Anwendungsdaten aus AUTOSAR COM sowie Diagnose-PDUs aus dem DCM werden über PduR und IpduM bzw. über das TTCAN Transport Protocol an das TTCAN Interface gereicht. Das TTCAN Interface abstrahiert den Hardwarezugriff und bedient den TTCAN Driver für zeitgesteuerte Nachrichtenübertragungen (kontinuierliche Übertragung über konfigurierte Tx-Trigger in exklusiven Zeitfenstern) sowie den CAN Transceiver.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektur-Referenzmodell für die Einbettung des TTCAN-Kommunikationsstapels in AUTOSAR. Das Modul <code>TTCAN Interface</code> stellt die zentrale hardwareunabhängige Vermittlungsschicht für TTCAN dar. Es bedient PDU Router, Transportprotokoll, State Manager und Network Management und standardisiert den Zugriff auf hardwarenahe Treiber (<code>TTCAN Driver</code>) sowie Transceiver. Implementierer müssen die korrekte funktionale Anbindung an PduR, TTCANSM und TTCAN Driver gemäß AUTOSAR-SWS-Vorgaben gewährleisten.</p>"}], "trans": [{"from": "FIG-f531b38899c9f05d", "to": "FIG-fe62a074a22c7fb5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
